'use client';

import {
  Checkbox as CheckboxPrimitive,
  useCheckbox,
  useCheckboxContext,
  useCheckboxGroup,
  useCheckboxGroupContext,
} from '@ark-ui/react/checkbox';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { CheckIcon, IndeterminateIcon } from '@/lib/moduix/icons/ui';
import styles from './Checkbox.module.css';

type CheckboxSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type CheckboxRootProps = ComponentProps<typeof CheckboxPrimitive.Root> & { size?: CheckboxSize };
type CheckboxRootProviderProps = ComponentProps<typeof CheckboxPrimitive.RootProvider> & {
  size?: CheckboxSize;
};

const Checkbox = forwardRef<ComponentRef<typeof CheckboxPrimitive.Root>, CheckboxRootProps>(
  function Checkbox({ className, size = 'md', ...props }, ref) {
    return (
      <CheckboxPrimitive.Root
        ref={ref}
        className={clsx(styles.root, className)}
        {...props}
        data-size={size}
        data-slot="checkbox-root"
      />
    );
  },
);

const CheckboxRootProvider = forwardRef<
  ComponentRef<typeof CheckboxPrimitive.RootProvider>,
  CheckboxRootProviderProps
>(function CheckboxRootProvider({ className, size = 'md', ...props }, ref) {
  return (
    <CheckboxPrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-size={size}
      data-slot="checkbox-root-provider"
    />
  );
});

const CheckboxIndicator = forwardRef<
  ComponentRef<typeof CheckboxPrimitive.Indicator>,
  ComponentProps<typeof CheckboxPrimitive.Indicator>
>(function CheckboxIndicator({ className, children, indeterminate, ...props }, ref) {
  return (
    <CheckboxPrimitive.Indicator
      ref={ref}
      className={clsx(styles.indicator, className)}
      indeterminate={indeterminate}
      {...props}
      data-slot="checkbox-indicator"
    >
      {children ?? (indeterminate ? <IndeterminateIcon /> : <CheckIcon />)}
    </CheckboxPrimitive.Indicator>
  );
});

const CheckboxControl = forwardRef<
  ComponentRef<typeof CheckboxPrimitive.Control>,
  ComponentProps<typeof CheckboxPrimitive.Control>
>(function CheckboxControl({ children, className, ...props }, ref) {
  return (
    <CheckboxPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="checkbox-control"
    >
      {children ?? (
        <>
          <CheckboxIndicator />
          <CheckboxIndicator indeterminate />
        </>
      )}
    </CheckboxPrimitive.Control>
  );
});

const CheckboxLabel = forwardRef<
  ComponentRef<typeof CheckboxPrimitive.Label>,
  ComponentProps<typeof CheckboxPrimitive.Label>
>(function CheckboxLabel({ className, ...props }, ref) {
  return (
    <CheckboxPrimitive.Label
      ref={ref}
      className={clsx(styles.label, className)}
      {...props}
      data-slot="checkbox-label"
    />
  );
});

const CheckboxGroup = forwardRef<
  ComponentRef<typeof CheckboxPrimitive.Group>,
  ComponentProps<typeof CheckboxPrimitive.Group>
>(function CheckboxGroup({ className, ...props }, ref) {
  return (
    <CheckboxPrimitive.Group
      ref={ref}
      className={clsx(styles.group, className)}
      {...props}
      data-slot="checkbox-group"
    />
  );
});

const CheckboxContext = CheckboxPrimitive.Context;
const CheckboxHiddenInput = CheckboxPrimitive.HiddenInput;

export {
  Checkbox,
  CheckboxContext,
  CheckboxControl,
  CheckboxGroup,
  CheckboxHiddenInput,
  CheckboxIndicator,
  CheckboxLabel,
  CheckboxRootProvider,
  useCheckbox,
  useCheckboxContext,
  useCheckboxGroup,
  useCheckboxGroupContext,
};

export type { CheckboxRootProps, CheckboxRootProviderProps, CheckboxSize };

@layer moduix.components {
  .root {
    --_checkbox-size: var(--moduix-spacing-5);
    --_checkbox-icon-size: var(--moduix-spacing-3);

    display: inline-flex;
    align-items: center;
    gap: var(--moduix-checkbox-gap, var(--moduix-spacing-2));
    vertical-align: middle;
    color: var(--moduix-color-foreground);
    cursor: pointer;

    &[data-disabled],
    &[data-readonly] {
      cursor: default;
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }

    &[data-size='xs'] {
      --_checkbox-size: var(--moduix-spacing-3-5);
      --_checkbox-icon-size: var(--moduix-spacing-2);
    }

    &[data-size='sm'] {
      --_checkbox-size: var(--moduix-spacing-4);
      --_checkbox-icon-size: var(--moduix-spacing-2-5);
    }

    &[data-size='lg'] {
      --_checkbox-size: var(--moduix-size-xs);
      --_checkbox-icon-size: var(--moduix-spacing-3-5);
    }

    &[data-size='xl'] {
      --_checkbox-size: var(--moduix-spacing-7);
      --_checkbox-icon-size: var(--moduix-spacing-4);
    }
  }

  .control {
    box-sizing: border-box;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    width: var(--moduix-checkbox-size, var(--_checkbox-size));
    height: var(--moduix-checkbox-size, var(--_checkbox-size));
    border: var(--moduix-border-width-sm) solid
      var(--moduix-checkbox-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-checkbox-radius, var(--moduix-radius-xs));
    background-color: var(--moduix-checkbox-bg, var(--moduix-color-background));
    color: var(--moduix-checkbox-color, var(--moduix-color-primary-foreground));
    user-select: none;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    &[data-state='checked'],
    &[data-state='indeterminate'] {
      border-color: var(--moduix-checkbox-bg-checked, var(--moduix-color-primary));
      background-color: var(--moduix-checkbox-bg-checked, var(--moduix-color-primary));
    }

    &[data-focus-visible] {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-border-width-sm);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);
      color: var(--moduix-color-destructive-foreground);
      outline-color: var(--moduix-color-destructive);

      &[data-state='checked'],
      &[data-state='indeterminate'] {
        background-color: var(--moduix-color-destructive);
      }
    }

    @media (hover: hover) {
      &[data-state='unchecked'][data-hover]:not([data-readonly], [data-disabled]) {
        background-color: var(--moduix-color-accent);
      }
    }
  }

  .indicator {
    display: inline-flex;
    width: var(--moduix-checkbox-icon-size, var(--_checkbox-icon-size));
    height: var(--moduix-checkbox-icon-size, var(--_checkbox-icon-size));

    & > svg {
      width: 100%;
      height: 100%;
    }
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .group {
    display: flex;
    flex-direction: column;
    gap: var(--moduix-spacing-2);
  }
}
